const puppeteer = require('puppeteer');
const { PuppeteerScreenRecorder } = require('puppeteer-screen-recorder');

// CAIN Standard: H.264 High profile, CRF 23, medium preset, 4 Mbps
// Generated by batch_render.py — session_static_details
// See LESSONS_MASTER.md #01-#02 for encoding rationale, #04 for scroll polling pattern
(async () => {
  const browser = await puppeteer.launch();
  const page = await browser.newPage();

  await page.setViewport({ width: 1280, height: 720 });

  const recorder = new PuppeteerScreenRecorder(page, {
    videoCrf: 23,
    videoPreset: 'medium',
    videoPixelFormat: 'yuv420p',
    videoBitrate: 4000,
  });

  await page.goto('file:///C:/Users/clint/azazael/src/CODEX/SESSION_TEMPLATE/templates/session_static_details.html');
  await recorder.start('C:/Users/clint/azazael/src/CODEX/SESSION_TEMPLATE/videos/session_static_details_scrolling.mp4');

  let scrollComplete = false;

  await page.evaluate(() => {
    const scrollStep = 30;
    const scrollDelay = 600;

    const scrollInterval = setInterval(() => {
      if (window.scrollY + window.innerHeight >= document.body.scrollHeight - 50) {
        scrollComplete = true;
        clearInterval(scrollInterval);
        return;
      }
      window.scrollBy(0, scrollStep);
    }, scrollDelay);
  });

  // Wait for scroll to complete (with safety timeout)
  while (!scrollComplete) {
    await new Promise(r => setTimeout(r, 500));
    const isComplete = await page.evaluate(() => {
      return window.scrollY + window.innerHeight >= document.body.scrollHeight - 50;
    });
    if (isComplete) break;
  }

  // Hold at end for a moment
  await new Promise(r => setTimeout(r, 2000));

  await recorder.stop();
  await browser.close();

  console.log('Video saved: session_static_details_scrolling.mp4');
})();
